from pathlib import Path
R=Path.cwd()
def edit(name, changes):
 p=R/name;s=p.read_text()
 for old,new in changes:
  if s.count(old)!=1: raise ValueError(f'{name}: expected one target {old[:90]!r}, got {s.count(old)}')
  s=s.replace(old,new)
 p.write_text(s)
def section(name,start,end,replacement):
 p=R/name;s=p.read_text();a=s.index(start);b=s.index(end,a);p.write_text(s[:a]+replacement+'\n\n'+s[b:])
